"""Rebuild the original SVG catalogue illustrations. Optional; assets are bundled."""
from pathlib import Path
from catalog import PRODUCTS

OUT=Path(__file__).resolve().parent/'static'/'images'

def shapes(kind,c):
    if kind=='lamp': return f'''<ellipse cx="300" cy="448" rx="108" ry="14" fill="url(#metal)"/><path d="M287 258h26v177h-26z" fill="url(#metal)"/><path d="M157 263a143 130 0 0 1 286 0Z" fill="url(#body)"/><ellipse cx="300" cy="262" rx="143" ry="10" fill="{c}"/><ellipse cx="300" cy="262" rx="114" ry="5" fill="#f6dfb8" opacity=".8"/><path d="M182 224c21-49 46-68 84-77" stroke="#fff" stroke-width="6" opacity=".18" fill="none"/><ellipse cx="300" cy="437" rx="100" ry="11" fill="{c}"/>'''
