    if kind=='stand': return '''<path d="M168 350l230-45-31 107-171 15Z" fill="url(#metal)"/><path d="M204 205l242 72-40 79-247-75Z" fill="url(#body)"/><path d="M159 281l247 75v16l-247-74Z" fill="#777d79"/><path d="M213 245l152 44m-159-27 152 44" stroke="#6f7672" stroke-width="5" stroke-linecap="round"/><path d="M189 272l-15 25m225 36-15 25" stroke="#464f49" stroke-width="9"/>'''
