    if kind=='clock': return '''<circle cx="300" cy="300" r="150" fill="url(#body)"/><circle cx="300" cy="300" r="132" fill="#f3eee2"/><g stroke="#8e8b79" stroke-width="3"><path d="M300 180v13m0 214v13m-120-120h13m214 0h13m-205-85 9 9m152 152 9 9m0-170-9 9m-152 152-9 9"/></g><path d="M300 300l-57-44m57 44 48-74" stroke="#333c32" stroke-width="7" stroke-linecap="round"/><circle cx="300" cy="300" r="8" fill="#333c32"/>'''
